import { ActionDefinition } from '../../../Action'
import { ReferenceColumn, DocumentIdColumn, TableNameColumn } from '../../../../db'

export const moveAttachment = ActionDefinition({
    $id: '7159823353cc10103a33ddeeff7b1216',
    name: 'Move Attachment',
    description:
        'Moves an attachment to a target record. The source is an attachment record. You can dynamically add and configure fields for the record. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply.',
    category: 'a20738df9363130079b5925cf67ffb74',
    inputs: {
        source_attachment_record: ReferenceColumn({
            label: 'Source Attachment Record',
            mandatory: true,
            referenceTable: 'sys_attachment',
        }),
        target_record: DocumentIdColumn({
            label: 'Target Record',
            dependent: 'table',
            mandatory: true,
        }),
        table: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
    },
    outputs: {},
})
